/* eslint-env serviceworker */
/*
 * sw-extra.js
 * -------------------------------------------------------------------------
 * The main service worker (sw.js) is auto-generated by vite-plugin-pwa /
 * Workbox on every build, so it can't be hand-edited directly. This file is
 * stitched into it via `workbox.importScripts` in vite.config.js and adds
 * the event listeners Workbox's generator doesn't provide:
 *   - push                 show a notification when a push arrives
 *   - notificationclick     focus/open the app when a notification is tapped
 *   - sync                  replay queued offline file/task actions
 *   - periodicsync          refresh cached data on a schedule
 *
 * The actual replay/refresh logic (Dexie queues, Supabase calls) lives in
 * the page, not here — the service worker doesn't import that code, it just
 * wakes any open/controlled clients up and asks them to do the work, or
 * opens a client if none exist.
 * -------------------------------------------------------------------------
 */

self.addEventListener('push', (event) => {
  let payload = { title: 'FileVault Suite', body: 'You have a new update.' };
  if (event.data) {
    try {
      payload = { ...payload, ...event.data.json() };
    } catch {
      payload.body = event.data.text();
    }
  }

  const { title, ...options } = payload;
  event.waitUntil(
    self.registration.showNotification(title, {
      body: options.body,
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      data: { url: options.url || '/' },
      tag: options.tag || 'filevault-notification'
    })
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data?.url || '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          client.navigate(targetUrl);
          return client.focus();
        }
      }
      if (self.clients.openWindow) return self.clients.openWindow(targetUrl);
    })
  );
});

// ---------------------------------------------------------------------------
// Background Sync — replays the Dexie `syncQueue` (queued renames, uploads,
// moves, etc. made while offline) as soon as the browser has a stable
// connection again, even if the PWA window isn't open in the foreground.
// Registered from the client in src/lib/backgroundSync.js whenever an action
// gets queued while offline.
// ---------------------------------------------------------------------------
self.addEventListener('sync', (event) => {
  if (event.tag !== 'sync-pending-changes') return;
  event.waitUntil(notifyClients('SYNC_PENDING_CHANGES'));
});

// ---------------------------------------------------------------------------
// Periodic Background Sync — asks an open client to silently refresh its
// cached file/task list every so often, so data feels current on next
// launch even without a manual pull-to-refresh. Only fires on browsers/OS
// combinations that grant the periodic-background-sync permission (mainly
// installed PWAs on Chromium/Android); harmless no-op everywhere else.
// ---------------------------------------------------------------------------
self.addEventListener('periodicsync', (event) => {
  if (event.tag !== 'refresh-cached-data') return;
  event.waitUntil(notifyClients('REFRESH_CACHED_DATA'));
});

/** Posts a message to every open/controlled window; used by both sync events. */
async function notifyClients(type) {
  const clientList = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  clientList.forEach((client) => client.postMessage({ type }));
}
